    node.getAnimations().forEach(animation => animation.cancel());
    const rect = node.getBoundingClientRect();
    const at = { x: rect.left - origin.left, y: rect.top - origin.top };
    return [node, at] as const;
  });
}
useLayoutEffect(() => {
