import postgres from "postgres";
process.loadEnvFile(".env.qa");
const db = postgres(process.env.SUPABASE_DB_URL, { max: 1, onnotice: () => {} });
const [{ id }] = await db`select w.id from public.workspaces w join auth.users u on u.id=w.owner_id where u.email=${process.env.E2E_USER_EMAIL}`;
if (process.argv[2] === "add") for (let i = 0; i < Number(process.argv[3] ?? 40); i++) await db`insert into public.accounts(workspace_id,name,currency_code,type) values(${id},${`ZZ seed ${i}`},'EUR','checking')`;
else await db`delete from public.accounts where workspace_id=${id} and name like 'ZZ seed %'`;
console.log((await db`select count(*)::int n from public.accounts where workspace_id=${id}`)[0].n);
await db.end();
EOF
